import { Router, Request, Response } from 'express';
import { z } from 'zod';

// Zod schemas for input validation
const createUserSchema = z.object({
  name: z.string().min(1, 'Name is required').max(100, 'Name must be 100 characters or less'),
  email: z.string().email('Invalid email address'),
});

const updateUserSchema = z.object({
  name: z.string().min(1).max(100).optional(),
  email: z.string().email('Invalid email address').optional(),
}).refine(data => data.name !== undefined || data.email !== undefined, {
  message: 'At least one field (name or email) must be provided',
});

const paramIdSchema = z.object({
  id: z.string().uuid('Invalid user ID format'),
});

interface User {
  id: string;
  name: string;
  email: string;
  createdAt: Date;
  updatedAt: Date;
}

const router = Router();
const users: Map<string, User> = new Map();

// Helper to format Zod errors
function formatZodErrors(error: z.ZodError): string[] {
  return error.errors.map(e => `${e.path.join('.')}: ${e.message}`);
}

// GET /api/users - List all users
router.get('/', (req: Request, res: Response) => {
  const allUsers = Array.from(users.values());
  res.json({ data: allUsers, count: allUsers.length });
});

// GET /api/users/:id - Get user by ID
router.get('/:id', (req: Request, res: Response) => {
  const paramResult = paramIdSchema.safeParse(req.params);
  if (!paramResult.success) {
    return res.status(400).json({ error: 'Invalid user ID format', details: formatZodErrors(paramResult.error) });
  }

  const user = users.get(req.params.id);
  if (!user) {
    return res.status(404).json({ error: 'User not found' });
  }
  res.json({ data: user });
});

// POST /api/users - Create a new user
router.post('/', (req: Request, res: Response) => {
  const result = createUserSchema.safeParse(req.body);
  if (!result.success) {
    return res.status(400).json({ error: 'Validation failed', details: formatZodErrors(result.error) });
  }

  const { name, email } = result.data;
  const id = crypto.randomUUID();
  const now = new Date();
  const newUser: User = {
    id,
    name,
    email,
    createdAt: now,
    updatedAt: now,
  };

  users.set(id, newUser);
  res.status(201).json({ data: newUser });
});

// PUT /api/users/:id - Update a user
router.put('/:id', (req: Request, res: Response) => {
  const paramResult = paramIdSchema.safeParse(req.params);
  if (!paramResult.success) {
    return res.status(400).json({ error: 'Invalid user ID format', details: formatZodErrors(paramResult.error) });
  }

  const user = users.get(req.params.id);
  if (!user) {
    return res.status(404).json({ error: 'User not found' });
  }

  const bodyResult = updateUserSchema.safeParse(req.body);
  if (!bodyResult.success) {
    return res.status(400).json({ error: 'Validation failed', details: formatZodErrors(bodyResult.error) });
  }

  const { name, email } = bodyResult.data;
  const updatedUser: User = {
    ...user,
    name: name ?? user.name,
    email: email ?? user.email,
    updatedAt: new Date(),
  };

  users.set(req.params.id, updatedUser);
  res.json({ data: updatedUser });
});

