/**
 * User Model - TypeScript type definitions for user management
 *
 * These types are shared across routes, services, and middleware.
 * The Zod schemas in routes/users.ts provide runtime validation
 * while these types provide compile-time type safety.
 */

/** Base user entity as stored in the data layer */
export interface User {
  id: string;
  name: string;
  email: string;
  createdAt: Date;
  updatedAt: Date;
}

/** Input type for creating a new user (POST /api/users) */
export interface CreateUserInput {
  name: string;
  email: string;
}

/** Input type for updating a user (PUT /api/users/:id) */
export interface UpdateUserInput {
  name?: string;
  email?: string;
}

/** API response wrapper for a single user */
export interface UserResponse {
  data: User;
}

/** API response wrapper for a list of users */
export interface UserListResponse {
  data: User[];
  count: number;
}

/** API error response */
export interface ApiErrorResponse {
  error: string;
  details?: string[];
}

/** User record as returned from a database query (dates as strings) */
export interface UserRecord {
  id: string;
  name: string;
  email: string;
  created_at: string;
  updated_at: string;
}

/** Convert a database record to a User entity */
export function toUser(record: UserRecord): User {
  return {
    id: record.id,
    name: record.name,
    email: record.email,
    createdAt: new Date(record.created_at),
    updatedAt: new Date(record.updated_at),
  };
}

/** Convert a User entity to a plain object for JSON serialization */
export function toUserJSON(user: User): Record<string, unknown> {
  return {
    id: user.id,
    name: user.name,
    email: user.email,
    createdAt: user.createdAt.toISOString(),
    updatedAt: user.updatedAt.toISOString(),
  };
}
